        FamousDua(28, "پانی پینے کے بعد کی دعا", "کھانا پینا", "الْحَمْدُ لِلَّهِ الَّذِي سَقَانَا عَذْبًا فُرَاتًا بِرَحْمَتِهِ وَلَمْ يَجْعَلْهُ مِلْحًا أُجَاجًا بِذُنُوبِنَا", "Alhamdu lillahilladhi saqana 'adhban furatan...", "تمام تعریفیں اس اللہ کے لیے ہیں جس نے اپنی رحمت سے ہمیں میٹھا خوشگوار پانی پلایا اور ہمارے گناہوں کی وجہ سے اسے کھاری کڑوا نہیں بنایا۔", "معجم طبرانی"),
        FamousDua(29, "سواری پر بیٹھنے کی دعا", "سفر و سواری", "بِسْمِ اللَّهِ الْحَمْدُ لِلَّهِ سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ", "Bismillah, Alhamdulillah, Subhanalladhi sakhkhara lana hadha...", "اللہ کے نام سے، تمام تعریف اللہ کے لیے، پاک ہے وہ ذات جس نے اس سواری کو ہمارے قابو میں کیا اور ہم اسے قابو کرنے والے نہ تھے اور بے شک ہم اپنے رب کی طرف لوٹنے والے ہیں۔", "سنن ترمذی 3446"),
        FamousDua(30, "سفر کی مکمل مسنون دعا", "سفر و سواری", "سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى وَمِنَ الْعَمَلِ مَا تَرْضَى اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الْأَهْلِ", "Subhanalladhi sakhkhara lana... Allahumma inna nas'aluka fi safarina hadhal-birra wat-taqwa...", "پاک ہے وہ جس نے اسے ہمارے قابو میں کیا حالانکہ ہم اسے قابو میں لانے والے نہ تھے اور ہم اپنے رب کی طرف لوٹنے والے ہیں، اے اللہ ہم اس سفر میں تجھ سے نیکی، تقوی اور ایسے عمل کا سوال کرتے ہیں جسے تو پسند کرے، اے اللہ ہمارے لیے یہ سفر آسان کر دے اور اس کی دوری کو ہمارے لیے لپیٹ دے، اے اللہ تو ہی سفر میں ساتھی ہے اور گھر والوں میں خلیفہ ہے۔", "صحیح مسلم 1342 مکمل متن"),
