        FamousDua(34, "نئے شہر میں داخل ہونے کی دعا", "سفر و سواری", "اللَّهُمَّ بَارِكْ لَنَا فِيهَا اللَّهُمَّ ارْزُقْنَا جَنَاهَا وَحَبِّبْنَا إِلَى أَهْلِهَا وَحَبِّبْ صَالِحِي أَهْلِهَا إِلَيْنَا", "Allahumma barik lana fiha...", "اے اللہ ہمارے لیے اس بستی میں برکت دے، اے اللہ ہمیں اس کے پھل عطا فرما، ہمیں اس کے رہنے والوں کا محبوب بنا اور اس کے نیک رہنے والوں کو ہمارا محبوب بنا۔", "معجم طبرانی"),
        FamousDua(35, "منزل پر اترنے کی دعا", "سفر و سواری", "رَبِّ أَنْزِلْنِي مُنْزَلًا مُبَارَكًا وَأَنْتَ خَيْرُ الْمُنْزِلِينَ", "Rabbi anzilni munzalam mubarakan wa Anta khairul-munzilin", "اے میرے رب! مجھے بابرکت منزل پر اتار اور تو بہترین اتارنے والا ہے۔", "سورۃ المؤمنون 29"),
        FamousDua(36, "صبح کے وقت کی دعا", "صبح و شام", "أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ وَالْحَمْدُ لِلَّهِ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ", "Asbahna wa asbahal-mulku lillah...", "ہم نے صبح کی اور ساری بادشاہت نے اللہ کے لیے صبح کی، تمام تعریف اللہ کے لیے، اللہ کے سوا کوئی معبود نہیں وہ اکیلا ہے اس کا کوئی شریک نہیں، اسی کی بادشاہت ہے اور اسی کے لیے حمد ہے اور وہ ہر چیز پر قادر ہے، اے میرے رب میں تجھ سے اس دن کی بھلائی اور اس کے بعد کی بھلائی کا سوال کرتا ہوں اور اس دن کے شر اور اس کے بعد کے شر سے تیری پناہ مانگتا ہوں۔", "صحیح مسلم 2723"),
        FamousDua(37, "شام کے وقت کی دعا", "صبح و شام", "أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ وَالْحَمْدُ لِلَّهِ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا", "Amsayna wa amsal-mulku lillah...", "ہم نے شام کی اور ساری بادشاہت نے اللہ کے لیے شام کی، تمام تعریف اللہ کے لیے ہے، اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اسی کی بادشاہت اور اسی کی حمد ہے اور وہ ہر چیز پر قادر ہے، اے میرے رب میں اس رات کی بھلائی اور اس کے بعد کی بھلائی کا سوال کرتا ہوں۔", "صحیح مسلم 2723"),
        FamousDua(38, "ہر نقصان سے حفاظت کی دعا", "صبح و شام", "بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ", "Bismillahilladhi la yadurru ma'asmihi shai'un...", "اللہ کے نام سے جس کے نام کی برکت سے زمین و آسمان میں کوئی چیز نقصان نہیں پہنچا سکتی اور وہ خوب سننے والا خوب جاننے والا ہے۔ صبح و شام تین بار پڑھنے سے کوئی چیز نقصان نہیں پہنچاتی۔", "سنن ابو داؤد 5088"),
        FamousDua(39, "سید الاستغفار", "صبح و شام", "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ", "Allahumma Anta Rabbi la ilaha illa Anta...", "اے اللہ تو میرا رب ہے تیرے سوا کوئی معبود نہیں، تو نے مجھے پیدا کیا اور میں تیرا بندہ ہوں اور اپنی طاقت بھر تیرے عہد اور وعدے پر قائم ہوں، میں اپنے کیے ہوئے کے شر سے تیری پناہ مانگتا ہوں، میں تیرے سامنے تیری نعمت کا اقرار کرتا ہوں اور اپنے گناہ کا اعتراف کرتا ہوں، پس مجھے بخش دے کیونکہ تیرے سوا کوئی گناہ نہیں بخشتا۔ صبح شام پڑھنے والا اگر اسی دن مر جائے تو جنتی ہے۔", "صحیح بخاری 6306"),
        FamousDua(40, "سو بار تسبیح کی فضیلت", "صبح و شام", "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ", "SubhanAllahi wa bihamdihi", "اللہ پاک ہے اپنی تعریف کے ساتھ۔ جو صبح و شام سو بار یہ پڑھے، قیامت کے دن اس سے بہتر عمل کوئی نہیں لائے گا سوائے اس کے جس نے اس جیسا یا اس سے زیادہ کیا ہو۔", "صحیح بخاری 6405"),
        FamousDua(41, "ہر مخلوق کے شر سے پناہ", "صبح و شام", "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ", "A'udhu bikalimatillahit-tammati min sharri ma khalaq", "میں اللہ کے مکمل کلمات کے ذریعے ہر اس چیز کے شر سے پناہ مانگتا ہوں جو اس نے پیدا کی ہے۔ شام کو تین بار پڑھنا۔", "صحیح مسلم 2708"),
        FamousDua(42, "صبح کے وقت رزق و علم کی دعا", "صبح و شام", "اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلًا مُتَقَبَّلًا", "Allahumma inni as'aluka 'ilman nafi'an...", "اے اللہ! میں تجھ سے نفع دینے والا علم، پاکیزہ رزق اور قبول ہونے والا عمل مانگتا ہوں۔", "سنن ابن ماجہ 925"),
        FamousDua(43, "بیمار کے لیے شفاء کی مکمل دعا", "حفاظت و شفاء", "اللَّهُمَّ رَبَّ النَّاسِ أَذْهِبِ الْبَأْسَ اشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا يُغَادِرُ سَقَمًا", "Allahumma Rabban-nas adhhibil-ba'sa ishfi...", "اے اللہ! لوگوں کے رب! تکلیف دور کر دے، شفا دے، تو ہی شفا دینے والا ہے، تیری شفا کے سوا کوئی شفا نہیں، ایسی شفا عطا فرما جو کوئی بیماری باقی نہ چھوڑے۔", "صحیح بخاری 5743"),
        FamousDua(44, "نظر بد اور ہر زہریلی چیز سے حفاظت", "حفاظت و شفاء", "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ", "A'udhu bikalimatillahit-tammati min kulli shaytanin wa hammah...", "میں اللہ کے مکمل کلمات کے ذریعے ہر شیطان، ہر زہریلے جانور اور ہر لگنے والی نظر بد سے پناہ مانگتا ہوں۔ نبی ﷺ حسن و حسین کے لیے یہ دعا پڑھتے تھے۔", "صحیح بخاری 3371"),
        FamousDua(45, "جامع عافیت کی دعا", "حفاظت و شفاء", "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي", "Allahumma inni as'alukal-'afiyata fid-dunya wal-akhirah...", "اے اللہ میں تجھ سے دنیا و آخرت میں عافیت کا سوال کرتا ہوں، اے اللہ میں اپنے دین، دنیا، اہل و مال میں معافی اور عافیت کا سوال کرتا ہوں، اے اللہ میرے عیبوں کو چھپا دے اور میرے خوف کو امن سے بدل دے۔", "سنن ابو داؤد 5074"),
        FamousDua(46, "ہر پریشانی میں کافی دعا", "حفاظت و شفاء", "حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ", "HasbunAllahu wa ni'mal Wakeel", "ہمیں اللہ کافی ہے اور وہ بہترین کارساز ہے۔ ابراہیم علیہ السلام نے آگ میں ڈالے جاتے وقت یہی کہا تھا۔", "سورۃ آل عمران 173"),
        FamousDua(47, "دشمن کے شر سے حفاظت", "حفاظت و شفاء", "اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ", "Allahumma inna naj'aluka fi nuhurihim wa na'udhu bika min shururihim", "اے اللہ! ہم تجھے ان کے مقابلے میں پیش کرتے ہیں اور ان کے شر سے تیری پناہ میں آتے ہیں۔", "سنن ابو داؤد 1537"),
        FamousDua(48, "بخار اور جسمانی تکلیف کی دعا", "حفاظت و شفاء", "بِسْمِ اللَّهِ الْكَبِيرِ أَعُوذُ بِاللَّهِ الْعَظِيمِ مِنْ شَرِّ كُلِّ عِرْقٍ نَعَّارٍ وَمِنْ شَرِّ حَرِّ النَّارِ", "Bismillahil-kabir, A'udhu billahil-'azim...", "بزرگی والے اللہ کے نام سے، میں عظمت والے اللہ کی پناہ چاہتا ہوں ہر بھڑکنے والی رگ کے شر سے اور آگ کی گرمی کے شر سے۔", "سنن ابن ماجہ 3590"),
        FamousDua(49, "جسم کے درد کی دعا", "حفاظت و شفاء", "بِسْمِ اللَّهِ ثَلَاثًا أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ سَبْعَ مَرَّاتٍ", "Bismillah (3x), A'udhu billahi wa qudratihi min sharri ma ajidu wa uhadhir (7x)", "درد کی جگہ پر ہاتھ رکھ کر تین بار بسم اللہ اور سات بار یہ دعا پڑھے: میں اللہ اور اس کی قدرت کی پناہ مانگتا ہوں اس چیز کے شر سے جو میں محسوس کر رہا ہوں اور جس سے ڈر رہا ہوں۔", "صحیح مسلم 2202"),
        FamousDua(50, "جامع استغفار", "مغفرت و رحمت", "أَسْتَغْفِرُ اللَّهَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ", "Astaghfirullahalladhi la ilaha illa Huwal-Hayyul-Qayyum wa atubu ilaih", "میں اس اللہ سے بخشش مانگتا ہوں جس کے سوا کوئی معبود نہیں، جو زندہ اور سب کو قائم رکھنے والا ہے اور میں اسی کی طرف توبہ کرتا ہوں۔ تین بار پڑھنے سے سمندر کے جھاگ برابر گناہ بھی معاف ہو جاتے ہیں۔", "سنن ابو داؤد 1517"),
        FamousDua(51, "تمام گناہوں کی بخشش کی دعا", "مغفرت و رحمت", "اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ دِقَّهُ وَجِلَّهُ وَأَوَّلَهُ وَآخِرَهُ وَعَلَانِيَتَهُ وَسِرَّهُ", "Allahummaghfir li dhanbi kullahu diqqahu wa jillahu...", "اے اللہ میرے تمام گناہ بخش دے، چھوٹے اور بڑے، پہلے اور آخر کے، ظاہر اور پوشیدہ۔", "صحیح مسلم 483"),
        FamousDua(52, "والدین کے لیے مغفرت", "مغفرت و رحمت", "رَبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ", "Rabbighfir li wa liwalidayya wa lil-mu'minina yawma yaqumul-hisab", "اے میرے رب! مجھے اور میرے والدین کو اور سب مومنوں کو اس دن بخش دینا جس دن حساب قائم ہوگا۔", "سورۃ ابراہیم 41"),
        FamousDua(53, "جنت اور جہنم سے پناہ", "مغفرت و رحمت", "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ", "Allahumma inni as'alukal-jannata wa a'udhu bika minan-nar", "اے اللہ! میں تجھ سے جنت کا سوال کرتا ہوں اور جہنم کی آگ سے تیری پناہ مانگتا ہوں۔", "سنن ابو داؤد 792"),
        FamousDua(54, "اللہ کی محبت کی دعا", "مغفرت و رحمت", "اللَّهُمَّ إِنِّي أَسْأَلُكَ حُبَّكَ وَحُبَّ مَنْ يُحِبُّكَ وَحُبَّ عَمَلٍ يُقَرِّبُنِي إِلَى حُبِّكَ", "Allahumma inni as'aluka hubbaka wa hubba man yuhibbuka...", "اے اللہ! میں تجھ سے تیری محبت کا سوال کرتا ہوں اور اس شخص کی محبت کا جو تجھ سے محبت کرتا ہے اور اس عمل کی محبت کا جو مجھے تیری محبت کے قریب کر دے۔", "سنن ترمذی 3235"),
        FamousDua(55, "رحمت اور ہدایت کی دعا", "مغفرت و رحمت", "اللَّهُمَّ ارْحَمْنِي وَاهْدِنِي وَعَافِنِي وَارْزُقْنِي", "Allahummarhamni wahdini wa 'afini warzuqni", "اے اللہ مجھ پر رحم فرما، مجھے ہدایت دے، مجھے عافیت دے اور مجھے رزق عطا فرما۔ دو سجدوں کے درمیان یہی جامع دعا ہے۔", "صحیح مسلم 2696"),
        FamousDua(56, "مشکل کو آسان کرنے کی دعا", "مشکل و حاجت", "اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا", "Allahumma la sahla illa ma ja'altahu sahla...", "اے اللہ! کوئی آسانی نہیں مگر جسے تو آسان کر دے اور تو جب چاہے مشکل کو آسان کر دیتا ہے۔", "صحیح ابن حبان 2427"),
        FamousDua(57, "غم، فکر اور قرض سے نجات", "مشکل و حاجت", "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْبُخْلِ وَالْجُبْنِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ", "Allahumma inni a'udhu bika minal-hammi wal-hazan...", "اے اللہ! میں فکر و غم، عاجزی و سستی، بخل و بزدلی، قرض کے بوجھ اور لوگوں کے غلبے سے تیری پناہ مانگتا ہوں۔", "صحیح بخاری 6369"),
        FamousDua(58, "سخت مشکل میں پکار", "مشکل و حاجت", "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِي كُلَّهُ وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ", "Ya Hayyu Ya Qayyumu birahmatika astaghith...", "اے زندہ، اے قائم رکھنے والے! تیری رحمت کے وسیلے سے فریاد کرتا ہوں، میرے تمام معاملات درست فرما دے اور مجھے ایک آنکھ جھپکنے کے برابر بھی میرے نفس کے حوالے نہ کر۔", "مستدرک حاکم 545"),
        FamousDua(59, "حاجت پوری ہونے کی دعا", "مشکل و حاجت", "لَا إِلَهَ إِلَّا اللَّهُ الْحَلِيمُ الْكَرِيمُ سُبْحَانَ اللَّهِ رَبِّ الْعَرْشِ الْعَظِيمِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ وَعَزَائِمَ مَغْفِرَتِكَ", "La ilaha illAllahul-Halimul-Karim...", "بردبار و کریم اللہ کے سوا کوئی معبود نہیں، اللہ پاک ہے جو عرش عظیم کا رب ہے، تمام تعریفیں اللہ کے لیے ہیں جو سارے جہانوں کا رب ہے، میں تجھ سے تیری رحمت کے اسباب اور تیری بخشش کے قطعی وعدوں کا سوال کرتا ہوں۔", "سنن ترمذی 479 - صلاۃ الحاجہ"),
        FamousDua(60, "قرض اور تنگدستی سے نجات", "مشکل و حاجت", "اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ", "Allahummakfini bihalalika 'an haramika...", "اے اللہ! مجھے اپنے حلال کے ساتھ حرام سے کافی ہو جا اور اپنے فضل سے اپنے سوا ہر کسی سے بے نیاز کر دے۔", "سنن ترمذی 3563"),
        FamousDua(61, "دنیا و آخرت کی بھلائی", "قرآنی دعائیں", "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ", "Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan...", "اے ہمارے رب! ہمیں دنیا میں بھلائی عطا فرما اور آخرت میں بھی بھلائی عطا فرما اور ہمیں آگ کے عذاب سے بچا لے۔ سب سے زیادہ پڑھی جانے والی قرآنی دعا۔", "سورۃ البقرۃ 201"),
        FamousDua(62, "معافی اور نصرت کی جامع دعا", "قرآنی دعائیں", "رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ", "Rabbana la tu'akhidhna in nasina aw akhta'na...", "اے ہمارے رب! اگر ہم بھول جائیں یا خطا کر بیٹھیں تو ہماری گرفت نہ کرنا، اے ہمارے رب! ہم پر وہ بوجھ نہ ڈال جیسا تو نے ہم سے پہلے لوگوں پر ڈالا، اے ہمارے رب! ہم پر وہ بوجھ نہ ڈال جس کی ہمیں طاقت نہ ہو، اور ہمیں معاف کر دے، بخش دے اور ہم پر رحم فرما، تو ہمارا مولا ہے پس کافر قوم کے مقابلے میں ہماری مدد فرما۔", "سورۃ البقرۃ 286"),
        FamousDua(63, "دل کی استقامت", "قرآنی دعائیں", "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ الْوَهَّابُ", "Rabbana la tuzigh qulubana ba'da idh hadaitana...", "اے ہمارے رب! جب تو ہمیں ہدایت دے چکا تو ہمارے دلوں کو ٹیڑھا نہ کر اور ہمیں اپنے پاس سے رحمت عطا فرما، بے شک تو بہت عطا کرنے والا ہے۔", "سورۃ آل عمران 8"),
        FamousDua(64, "ایمان کے بعد مغفرت", "قرآنی دعائیں", "رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ", "Rabbana innana amanna faghfir lana dhunubana wa qina 'adhaban-nar", "اے ہمارے رب! بے شک ہم ایمان لائے پس ہمارے گناہ بخش دے اور ہمیں آگ کے عذاب سے بچا لے۔", "سورۃ آل عمران 16"),
        FamousDua(65, "گواہوں میں لکھے جانے کی دعا", "قرآنی دعائیں", "رَبَّنَا آمَنَّا بِمَا أَنزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ", "Rabbana amanna bima anzalta wattaba'nar-rasula...", "اے ہمارے رب! ہم اس پر ایمان لائے جو تو نے نازل کیا اور ہم نے رسول کی پیروی کی پس ہمیں گواہی دینے والوں کے ساتھ لکھ لے۔", "سورۃ آل عمران 53"),
